SELECT w->>'kind' as kind, w->>'x1' as x1, w->>'y1' as y1, w->>'x2' as x2, w->>'y2' as y2, w->>'door_open' as door_open, abs((w->>'x2')::float - (w->>'x1')::float) as dx, abs((w->>'y2')::float - (w->>'y1')::float) as dy FROM tactical_scenes ts, jsonb_array_elements(ts.walls::jsonb) w WHERE ts.id = '557378d7-557c-45b7-bf3c-42c2f73840a0' AND w->>'kind' = 'wall' AND (SELECT count(*) FROM jsonb_array_elements(ts2.walls::jsonb) ww WHERE ts2.id = ts.id AND ww->>'kind' = 'window' AND abs((ww->>'x1')::float - (ww->>'x2')::float) > 0.05 AND abs((ww->>'y1')::float - (ww->>'y2')::float) > 0.05) > 0 ORDER BY (w->>'y1')::float LIMIT 20;
